<?php
declare(strict_types=1);
if(!defined('CWP_BOOT')){http_response_code(404);exit;}
require_once CWP_CODE_ROOT.'/app/providers/service_observations.php';
function service_observations_label(string $state):string {return match($state){'observed'=>'Latest saved read available','stale'=>'Latest saved read is out of date','partial'=>'Latest read was incomplete','unfinished'=>'Latest refresh has no saved outcome','absent'=>'Assigned package was not reported in the latest read','assignment_changed'=>'The studio needs to confirm this assignment','not_shared'=>'History sharing is off','complete'=>'Saved read','unavailable','refused','access_changed','credential'=>'Latest refresh did not provide an observation',default=>'History is unavailable'};}
function service_observations_render(array $history,string $linkId,bool $admin=false):void {
    echo '<div data-service-history><p><strong>'.esc(service_observations_label($history['status'])).'</strong></p><p class="hint">Saved provider observations, not live uptime or confirmation that a service was provisioned. Account-wide coverage is unknown. Earlier successful reads remain historical when a later read fails.</p>';
    foreach($history['rows'] as $row){echo '<article class="workspace-message" data-service-observation><p><strong>'.esc(gmdate('Y-m-d H:i:s',$row['observed_epoch'])).' UTC</strong> · '.esc(service_observations_label($row['state'])).'</p>';$p=$row['package'];if($p){echo '<h3 style="overflow-wrap:anywhere">'.esc($p['name']).'</h3><p>Observed setting: <strong>'.($p['enabled']?'Enabled':'Disabled').'</strong></p><p>Package type: '.esc($p['package_type_name']??'Not reported').'</p><p style="overflow-wrap:anywhere">Reported names: '.esc(implode(', ',$p['names'])).'</p>';if($row['state']==='partial')echo '<p class="hint">Other entries in this read could not be retained. This is an incomplete observation.</p>';}elseif($row['state']==='complete')echo '<p>No matching package was reported. This alone does not prove deletion or cancellation.</p>';else echo '<p>No package details are claimed for this read.</p>';echo '</article>';}
    if($history['next']>0){$args=['service_link'=>$linkId,'history_before'=>$history['next']];$url=$admin?admin_url('provider-settings',$args).'#service-observations':studio_url(['service_history'=>1]+$args);echo '<a class="btn outline" href="'.esc($url).'">Older observations</a>';}echo '</div>';
}
function service_observations_admin_render():void {
    provider_settings_manager();echo '<section class="workspace-card" id="service-observations"><h2>Client hosting history</h2><p>Share saved observations from the selected read onward. Earlier reads and other client packages stay private. No provider request is made here.</p>';
    try{$ready=service_observations_ready();if(!$ready){echo '<form method="post">';admin_action('provider_inventory_history_prepare');admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<button class="btn gold">Enable hosting history</button></form></section>';return;}
        $page=max(1,min(10000,(int)($_GET['history_page']??1)));$links=all('SELECT l.*,c.name AS client_name FROM '.table('provider_package_links').' l JOIN '.table('studio_clients').' c ON c.id=l.client_id ORDER BY l.id LIMIT 20 OFFSET '.(($page-1)*20));if(!$links)echo '<p>Assign a hosting package to a client first.</p>';
        foreach($links as $l){$policy=service_observations_load($l['id']);$latest=service_observations_reads($l['profile_id'])[0]??null;$before=(is_string($_GET['service_link']??null)&&$_GET['service_link']===$l['id'])?max(0,(int)($_GET['history_before']??0)):0;echo '<article class="workspace-card" data-service-history-owner><h3>'.esc($l['client_name']).' · Package '.esc((string)$l['package_id']).'</h3><p>'.($policy&&$policy['document']['enabled']?'Sharing enabled for the approved assignment.':'History sharing is off.').'</p>';
            echo '<form method="post">';admin_action('provider_inventory_history_change');foreach(['link_id'=>$l['id'],'expected_id'=>$policy['document']['id']??'','event_id'=>bin2hex(random_bytes(16)),'refresh_id'=>$latest['id']??''] as $name=>$value)echo '<input type="hidden" name="'.$name.'" value="'.esc($value).'">';admin_input('current_password','Your current owner password','','password','required autocomplete="current-password"');echo '<div class="button-row"><button class="btn gold" name="sharing" value="enable">Share from latest saved read</button>';if($policy)echo '<button class="btn outline" name="sharing" value="disable">Turn off sharing</button>';echo '</div><p class="hint">Enabling requires a complete saved read from the last 15 minutes and the current explicit assignment. Enabling again starts a new visible history boundary.</p></form>';
            try{$history=staff_locked(fn()=>staff_transaction(fn()=>service_observations_project($l['id'],$before)));service_observations_render($history,$l['id'],true);}catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</article>';
        }
        echo '<nav class="button-row" aria-label="Hosting history assignments">';if($page>1)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['history_page'=>$page-1])).'#service-observations">Previous assignments</a>';if(count($links)===20&&$page<10000)echo '<a class="btn outline" href="'.esc(admin_url('provider-settings',['history_page'=>$page+1])).'#service-observations">More assignments</a>';echo '</nav>';
    }catch(InvalidArgumentException|RuntimeException $e){if($e instanceof PDOException)throw $e;echo '<p class="notice error">'.esc($e->getMessage()).'</p>';}echo '</section>';
}
